function metricsBased(history, newCases) {
  const h = history.reduce((s, x) => s + x.hours, 0);
  const c = history.reduce((s, x) => s + x.cases, 0);
  return Math.round((newCases * h / c) * 10) / 10;
}

function threePoint(a, m, b) {
  const r2 = (x) => Math.round(x * 100) / 100;
  return { estimate: r2((a + 4 * m + b) / 6), sd: r2((b - a) / 6) };
}

function withRetests(hours, cycles, retestRatio) {
  return Math.round(hours * (1 + cycles * retestRatio) * 10) / 10;
}
